<script lang="ts">
 import {zh} from './zh';
 import {engine,type ScorePanels} from '../../bridge/engine.svelte';import AriaSymbol from './AriaSymbol.svelte';import catalog from './instruments.json';import {registerBack} from '../../ui/back';
 let {phone,onclose,onedit}:{phone:boolean;onclose:()=>void;onedit:(v:Record<string,unknown>)=>Promise<boolean>}=$props();
 let width=$state(innerWidth),height=$state(innerHeight),query=$state(''),genre=$state('common'),category=$state('all'),focused=$state('flute'),busy=$state(false),data=$state<ScorePanels>(engine.scorePanels()),removeID=$state(''),dragged=$state('');
 const genres=[['common','Common'],['all','All instruments'],['popular','Pop/Rock'],['jazz','Jazz'],['choral','Choral'],['orchestra','Orchestra'],['concertBand','Concert Band'],['marchingBand','Marching Band'],['electronic','Electronic Music'],['world','World Music'],['earlyMusic','Early Music'],['classroom','Classroom']];
 const categories=[['all','All Instruments'],['woodwinds','Woodwinds'],['freeReed','Free Reed'],['brass','Brass'],['pitchedPercussion','Pitched Percussion'],['unpitchedPercussion','Unpitched Percussion'],['marchingPercussion','Marching Percussion'],['bodyPercussion','Body Percussion'],['vocals','Vocals'],['keyboards','Keyboards'],['electronic','Electronic'],['pluckedStrings','Plucked Strings'],['bowedStrings','Bowed Strings']];
 const matching=$derived(catalog.filter(i=>(genre==='all'||i.genres.includes(genre))&&(!query||[i.name,i.englishName,i.id,i.category].some(v=>v.toLowerCase().includes(query.toLowerCase())))));
 const visibleCategories=$derived(categories.filter(([id])=>id==='all'||matching.some(i=>i.category===id)));
 const instruments=$derived(matching.filter(i=>category==='all'||i.category===category));
 const modalWidth=$derived(Math.min(Math.max(width-64,680),940)),modalHeight=$derived(Math.min(Math.max(height-170,560),760)),compact=$derived(modalWidth<780);
 $effect(()=>registerBack(()=>{if(removeID)removeID='';else onclose();return true;},110));
 async function add(id:string){busy=true;try{if(await onedit({op:'addInstrument',id}))data=engine.scorePanels();}finally{busy=false;}}
 async function remove(){busy=true;try{if(await onedit({op:'removeInstrument',id:removeID}))data=engine.scorePanels();removeID='';}finally{busy=false;}}
 function drop(id:string){if(!dragged||dragged===id)return;const source=data.parts.findIndex(p=>p.id===dragged),target=data.parts.findIndex(p=>p.id===id);engine.changeParts({op:'move-part',id:dragged,target:id,after:source<target});data=engine.scorePanels();dragged='';}
 const clef=(value:string)=>value==='bass'?'𝄢':value==='alto'?'𝄡':'𝄞';
</script>
<svelte:window bind:innerWidth={width} bind:innerHeight={height}/>
<div class="instrument-cover" class:phone><button class="cover-shade" aria-label="关闭乐器面板" onclick={onclose}></button><div class="instrument-picker" class:compact role="dialog" tabindex="-1" aria-modal="true" aria-label="增删乐器" style:width={phone?'100%':modalWidth+'px'} style:height={phone?'100%':modalHeight+'px'}>
 <header><button onclick={onclose}>关闭</button><strong>增删乐器</strong><button class="primary" onclick={onclose}>完成</button></header>
 <div class="search"><AriaSymbol name="magnifyingglass" size={16}/><input aria-label="搜索乐器" placeholder="搜索乐器" bind:value={query}/>{#if query}<button aria-label="清除搜索" onclick={()=>query=''}><AriaSymbol name="xmark.circle.fill" size={16}/></button>{/if}</div>
 {#if phone}<div class="phone-genres">{#each genres as [id,label]}<button class:chosen={genre===id} onclick={()=>{genre=id;category='all';}}>{zh(label)}</button>{/each}</div><div class="phone-categories">{#each visibleCategories as [id,label]}<button class:chosen={category===id} onclick={()=>category=id}>{zh(label)}</button>{/each}</div>{/if}
 <div class="columns" style:--genre-width={modalWidth>=820?'152px':compact?'128px':'140px'} style:--category-width={modalWidth>=820?'172px':compact?'146px':'158px'} style:--selected-width={modalWidth>=820?'250px':compact?'196px':'220px'}>
  {#if !phone}<aside class="genres">{#each genres as [id,label]}<button class:chosen={genre===id} onclick={()=>{genre=id;category='all';}}>{zh(label)}</button>{/each}</aside><aside class="categories">{#each visibleCategories as [id,label]}<button class:chosen={category===id} onclick={()=>category=id}>{zh(label)}</button>{/each}</aside>{/if}
  <div class="available">{#each instruments as instrument}<div class="instrument-row" class:focused={focused===instrument.id}><button class="instrument-name" onclick={()=>focused=instrument.id} ondblclick={()=>add(instrument.id)}><span class="clef">{clef(instrument.clef)}</span><span><strong>{instrument.name}</strong><small>{instrument.detail||zh(categories.find(([id])=>id===instrument.category)?.[1]||'乐器')}</small></span></button><button class="add" disabled={busy} aria-label={zh('Add '+instrument.name)} onclick={()=>add(instrument.id)}><AriaSymbol name="plus.circle.fill" size={phone?24:20}/></button></div>{/each}</div>
  <aside class="in-score"><h3>乐谱中（{data.parts.length}）</h3><div class="current-list">{#each data.parts as part}<div class="current-instrument" draggable={!busy} ondragstart={()=>dragged=part.id} ondragover={e=>e.preventDefault()} ondrop={e=>{e.preventDefault();drop(part.id);}} role="listitem"><AriaSymbol name="line.3.horizontal" size={13}/><strong>{part.name}</strong><button disabled={busy} aria-label={zh('Remove '+part.name)} onclick={()=>removeID=part.id}><AriaSymbol name="xmark.circle.fill" size={20}/></button></div>{/each}</div></aside>
 </div>
 </div>{#if removeID}<div class="remove-confirm" role="alertdialog" aria-modal="true" aria-label="移除乐器"><strong>移除这个乐器？</strong><p>这会移除该乐器及其乐谱内容。</p><div><button onclick={()=>removeID=''}>取消</button><button class="destructive" disabled={busy} onclick={remove}>移除</button></div></div>{/if}
</div>
<style>
 .instrument-cover{position:fixed;inset:0;z-index:85;display:grid;place-items:center;pointer-events:auto;color:#202020;font:14px system-ui,sans-serif;}.cover-shade{position:absolute;inset:0;background:#0000003d;border:0;border-radius:0;}.instrument-picker{position:relative;background:#fbfaf8;border-radius:18px;overflow:hidden;display:flex;flex-direction:column;box-shadow:0 16px 48px #0003;}.instrument-picker header{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:16px 22px;flex:none;}.instrument-picker header>button{min-width:104px;min-height:34px;border:0;background:none;text-align:left;color:#337864;font-size:16px;font-weight:500;}.instrument-picker header>strong{font-size:17px;white-space:nowrap;}.instrument-picker header>.primary{background:#337864;color:white;text-align:center;font-size:15px;border-radius:7px;padding:0 14px;}.search{flex:none;display:flex;align-items:center;gap:10px;padding:0 12px;height:42px;background:#00000008;border-radius:10px;margin:0 22px 12px;}.search input{flex:1;min-width:0;background:none;border:0;outline:none;font-size:16px;}.search>button{border:0;background:none;}.columns{display:flex;flex:1;min-height:0;}.columns>aside{overflow:auto;}.genres{width:var(--genre-width);flex:none;}.categories{width:var(--category-width);flex:none;border-left:1px solid #0002;border-right:1px solid #0002;}.genres>button,.categories>button{display:block;width:100%;min-height:42px;padding:10px 14px;text-align:left;border:0;border-radius:0;background:none;font-size:13px;font-weight:500;}.genres .chosen,.categories .chosen{background:#33786419;color:#337864;}.available{flex:1;min-width:0;overflow:auto;}.instrument-row{display:flex;align-items:center;min-height:62px;border-bottom:.5px solid #0000000c;}.instrument-row.focused{background:#3378640c;}.instrument-name{flex:1;min-width:0;display:flex;align-items:center;gap:12px;padding:10px 12px;border:0;background:none;text-align:left;}.clef{font-family:'Aria Bravura Text';font-size:32px;width:28px;flex:none;}.instrument-name strong{font-size:15px;font-weight:600;}.instrument-name small{display:block;font-size:12px;color:#0007;margin-top:2px;}.add{width:40px;min-height:44px;flex:none;background:none;border:0;color:#337864;display:grid;place-items:center;}.in-score{width:var(--selected-width);flex:none;border-left:1px solid #0002;background:#00000003;}.in-score h3{font-size:13px;color:#0009;padding:12px 16px;}.current-instrument{display:flex;align-items:center;gap:10px;padding:0 12px;min-height:52px;border-bottom:.5px solid #0001;}.current-instrument strong{flex:1;font-size:14px;}.current-instrument>button{border:0;background:none;min-height:44px;flex:none;color:#0006;}.phone .cover-shade{background:transparent;}.phone .instrument-picker{border-radius:0;}.phone .instrument-picker header{padding:16px 14px;}.phone .instrument-picker header>button{min-width:58px;}.phone .instrument-picker header>.primary{min-width:76px;font-size:13px;}.phone .search{margin:0 14px 10px;height:44px;border-radius:11px;}.phone-genres,.phone-categories{display:flex;gap:8px;overflow:auto;flex:none;padding:0 14px 10px;scrollbar-width:none;}.phone-genres>button{flex:none;min-height:34px;padding:0 14px;border:1px solid #0001;background:#00000004;border-radius:17px;white-space:nowrap;font-size:13px;font-weight:600;}.phone-genres>.chosen{background:#337864;color:white;border-color:#337864;}.phone-categories{gap:18px;border-bottom:.5px solid #0002;padding-bottom:0;}.phone-categories>button{flex:none;min-height:38px;border:0;border-bottom:2px solid transparent;background:none;font-size:13px;color:#0008;}.phone-categories>.chosen{color:#337864;border-bottom-color:#337864;}.phone .columns{flex-direction:column;}.phone .available{min-height:80px;}.phone .instrument-row{min-height:60px;}.phone .instrument-name strong{font-size:16px;}.phone .in-score{width:100%;max-height:230px;min-height:90px;border-left:0;border-top:1px solid #0002;display:flex;flex-direction:column;overflow:hidden;}.phone .in-score h3{padding:8px 16px;}.phone .current-list{overflow:auto;}.remove-confirm{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:min(310px,90%);padding:22px;background:white;border-radius:14px;box-shadow:0 0 0 200vmax #0005;z-index:5;}.remove-confirm p{margin:12px 0;font-size:14px;}.remove-confirm>div{display:flex;justify-content:end;gap:16px;}.remove-confirm button{border:0;background:none;min-height:44px;color:#007aff;}.remove-confirm .destructive{color:#f33;}button:disabled{opacity:.4;}
</style>
